#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<string> inputs;
    string line;
    getline(cin, line);
    istringstream iss(line);
    string token;
    while (iss >> token) {
        inputs.push_back(token);
    }
    int a, b;
    vector<int> nums;
    for (const auto& s : inputs) {
        nums.push_back(stoi(s));
    }
    sort(nums.begin(), nums.end());
    a = nums[0];
    b = nums[1];
    int factor = a * b;
    int check_value = 0;
    if (a == 1) {
        check_value = (b % 6 > 1 && b % 6 < 5) ? 1 : 0;
    } else if (a == 2) {
        int val = 0;
        switch (b) {
            case 2: val = 2; break;
            case 3: val = 1; break;
            case 7: val = 1; break;
            default: val = 0; break;
        }
        check_value = val;
    }
    int output = (~1 & (factor - 2 * check_value));
    cout << output << "\n";
    return 0;
}
